module LIFObuffer (
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

    reg [3:0] stack_mem [0:3];
    reg [1:0] SP;

    always @(posedge Clk) begin
        if (Rst) begin
            SP <= 4'b100;
            for (integer i = 0; i < 4; i++) begin
                stack_mem[i] <= 4'b0000;
            end
        end else if (EN) begin
            if (RW == 0 && SP != 0) begin
                stack_mem[SP - 1] <= dataIn;
                SP <= SP - 1;
            end else if (RW == 1 && SP != 4'b100) begin
                dataOut <= stack_mem[SP];
                stack_mem[SP] <= 4'b0000;
                SP <= SP + 1;
            end
        end
    end

    assign EMPTY = (SP == 4'b100);
    assign FULL = (SP == 4'b0000);

endmodule
